{"content":"/**
 * Client-side cart / quote / session state.
 *
 * Persisted to localStorage today. This provider is intentionally the only
 * place the UI touches cart state, so it can be swapped for an API-backed
 * cart (ERP or Lovable Cloud) without touching any screen.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { getProductBySlug, type Product } from "@/data/catalog";

export interface LineItem {
  slug: string;
  qty: number;
}

export interface ResolvedLine extends LineItem {
  product: Product;
  extended: number | null;
}

export interface QuoteRequest {
  id: string;
  createdAt: string;
  jobName: string;
  items: LineItem[];
  status: "Submitted" | "In review" | "Quoted";
}

export interface OrderRecord {
  id: string;
  createdAt: string;
  poNumber: string;
  total: number;
  items: LineItem[];
  status: "Processing" | "Shipped" | "Delivered";
}

export interface AccountSession {
  email: string;
  companyName: string;
  accountNumber: string;
  isAdmin: boolean;
}

interface StoreValue {
  cart: LineItem[];
  quoteList: LineItem[];
  cartNote: string;
  poNumber: string;
  quotes: QuoteRequest[];
  orders: OrderRecord[];
  session: AccountSession | null;
  addToCart: (slug: string, qty?: number) => void;
  addToQuote: (slug: string, qty?: number) => void;
  setQty: (slug: string, qty: number) => void;
  setQuoteQty: (slug: string, qty: number) => void;
  removeFromCart: (slug: string) => void;
  removeFromQuote: (slug: string) => void;
  clearCart: () => void;
  clearQuoteList: () => void;
  moveCartToQuote: () => void;
  setCartNote: (v: string) => void;
  setPoNumber: (v: string) => void;
  submitQuote: (jobName: string) => string;
  placeOrder: (po: string) => string;
  signIn: (email: string, isAdmin?: boolean) => void;
  signOut: () => void;
}

const StoreContext = createContext<StoreValue | null>(null);

const KEY = "pickrel-store-v1";

interface Persisted {
  cart: LineItem[];
  quoteList: LineItem[];
  cartNote: string;
  poNumber: string;
  quotes: QuoteRequest[];
  orders: OrderRecord[];
  session: AccountSession | null;
}

const EMPTY: Persisted = {
  cart: [],
  quoteList: [],
  cartNote: "",
  poNumber: "",
  quotes: [],
  orders: [],
  session: null,
};

export function StoreProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<Persisted>(EMPTY);
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(KEY);
      if (raw) setState({ ...EMPTY, ...(JSON.parse(raw) as Persisted) });
    } catch {
      /* ignore corrupted storage */
    }
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    try {
      window.localStorage.setItem(KEY, JSON.stringify(state));
    } catch {
      /* storage full or unavailable */
    }
  }, [state, hydrated]);

  const upsert = useCallback((list: LineItem[], slug: string, qty: number) => {
    const found = list.find((l) => l.slug === slug);
    if (found) return list.map((l) => (l.slug === slug ? { ...l, qty: l.qty + qty } : l));
    return [...list, { slug, qty }];
  }, []);

  const value = useMemo<StoreValue>(() => {
    const total = (items: LineItem[]) =>
      items.reduce((sum, l) => {
        const p = getProductBySlug(l.slug);
        return sum + (p?.price ?? 0) * l.qty;
      }, 0);

    return {
      ...state,
      addToCart: (slug, qty = 1) => setState((s) => ({ ...s, cart: upsert(s.cart, slug, qty) })),
      addToQuote: (slug, qty = 1) =>
        setState((s) => ({ ...s, quoteList: upsert(s.quoteList, slug, qty) })),
      setQty: (slug, qty) =>
        setState((s) => ({
          ...s,
          cart: s.cart.map((l) => (l.slug === slug ? { ...l, qty: Math.max(1, qty) } : l)),
        })),
      setQuoteQty: (slug, qty) =>
        setState((s) => ({
          ...s,
          quoteList: s.quoteList.map((l) => (l.slug === slug ? { ...l, qty: Math.max(1, qty) } : l)),
        })),
      removeFromCart: (slug) => setState((s) => ({ ...s, cart: s.cart.filter((l) => l.slug !== slug) })),
      removeFromQuote: (slug) =>
        setState((s) => ({ ...s, quoteList: s.quoteList.filter((l) => l.slug !== slug) })),
      clearCart: () => setState((s) => ({ ...s, cart: [], cartNote: "", poNumber: "" })),
      clearQuoteList: () => setState((s) => ({ ...s, quoteList: [] })),
      moveCartToQuote: () =>
        setState((s) => {
          let list = s.quoteList;
          for (const l of s.cart) list = upsert(list, l.slug, l.qty);
          return { ...s, quoteList: list };
        }),
      setCartNote: (v) => setState((s) => ({ ...s, cartNote: v })),
      setPoNumber: (v) => setState((s) => ({ ...s, poNumber: v })),
      submitQuote: (jobName) => {
        const id = `Q-${Date.now().toString().slice(-6)}`;
        setState((s) => ({
          ...s,
          quotes: [
            {
              id,
              createdAt: new Date().toISOString(),
              jobName,
              items: s.quoteList,
              status: "Submitted",
            },
            ...s.quotes,
          ],
          quoteList: [],
        }));
        return id;
      },
      placeOrder: (po) => {
        const id = `SO-${Date.now().toString().slice(-6)}`;
        setState((s) => ({
          ...s,
          orders: [
            {
              id,
              createdAt: new Date().toISOString(),
              poNumber: po,
              total: total(s.cart),
              items: s.cart,
              status: "Processing",
            },
            ...s.orders,
          ],
          cart: [],
          cartNote: "",
          poNumber: "",
        }));
        return id;
      },
      signIn: (email, isAdmin = false) =>
        setState((s) => ({
          ...s,
          session: {
            email,
            companyName: "Demo Mechanical Contractors",
            accountNumber: "PB-10482",
            isAdmin,
          },
        })),
      signOut: () => setState((s) => ({ ...s, session: null })),
    };
  }, [state, upsert]);

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

export function useStore(): StoreValue {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error("useStore must be used inside StoreProvider");
  return ctx;
}

export function resolveLines(items: LineItem[]): ResolvedLine[] {
  return items
    .map((l) => {
      const product = getProductBySlug(l.slug);
      if (!product) return null;
      return {
        ...l,
        product,
        extended: product.price === null ? null : product.price * l.qty,
      };
    })
    .filter((l): l is ResolvedLine => l !== null);
}

export function cartSubtotal(lines: ResolvedLine[]): number {
  return lines.reduce((s, l) => s + (l.extended ?? 0), 0);
}
